{"i":2,"result":{"status":"fulfilled","value":{"chunk_id":"039f5e","wall_time_seconds":0.000004468,"exit_code":0,"original_token_count":810,"output":""""Helpers for Dasel recursive descent and search selectors.

These operate on ordinary Python JSON-like values and are kept separate from
the query parser so the CLI implementation can use them directly.
"""

def _children(value):
    if isinstance(value, dict):
        return value.values()
    if isinstance(value, list):
        return value
    return ()


def recursive_values(root, key):
    """Return values at key in descendant objects, in depth-first order.

    The root object's own keys are not considered by the reference `..key`
    selector; its children are searched.
    """
    out = []
    def walk(value):
        if isinstance(value, dict):
            for k, v in value.items():
                if k == key:
                    out.append(v)
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    for child in _children(root):
        walk(child)
    return out


def search_objects(root, key, operator, expected):
    """Find descendant objects whose direct property satisfies a comparison."""
    def matches(value):
        if key not in value:
            return False
        actual = value[key]
        try:
            return {
                '==': lambda: actual == expected,
                '!=': lambda: actual != expected,
                '>': lambda: actual > expected,
                '<': lambda: actual < expected,
                '>=': lambda: actual >= expected,
                '<=': lambda: actual <= expected,
            }[operator]()
        except (KeyError, TypeError):
            return False

    out = []
    def walk(value):
        if isinstance(value, dict):
            if matches(value):
                out.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)
    # As with recursive descent, the top level itself isn't a candidate.
    for child in _children(root):
        walk(child)
    return out
