"""Standard-library CSV and default XML adapters."""
import csv
import io
import xml.etree.ElementTree as ET


def parse_csv(text, delimiter=','):
    reader = csv.DictReader(io.StringIO(text), delimiter=delimiter)
    return [{str(k): (v if v is not None else '') for k, v in row.items() if k is not None}
            for row in reader]


def _element(el):
    obj = {'-' + k: v for k, v in el.attrib.items()}
    text_parts = [el.text or '']
    for child in el:
        value = _element(child)
        key = child.tag
        if key in obj:
            old = obj[key]
            if not isinstance(old, list): old = [old]
            old.append(value)
            obj[key] = old
        else:
            obj[key] = value
        text_parts.append(child.tail or '')
    text = ''.join(text_parts)
    if not obj:
        return text
    if text:
        obj['#text'] = text
    return obj


def parse_xml(text):
    root = ET.fromstring(text)
    return {root.tag: _element(root)}


def dump_csv(value, delimiter=','):
    if not isinstance(value, list):
        raise ValueError('csv writer expects root output to be a slice/array, got ' + ('map' if isinstance(value, dict) else type(value).__name__))
    if not value:
        return ''
    if not all(isinstance(row, dict) for row in value):
        raise ValueError('error ranging slice: expected map values')
    fields=[]
    for row in value:
        for key in row:
            if key not in fields: fields.append(key)
    out=io.StringIO(newline='')
    writer=csv.DictWriter(out,fieldnames=fields,delimiter=delimiter,lineterminator='\n',extrasaction='ignore')
